1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		activatedAt time.Time
20		// terms 是本订阅段套餐条件的唯一事实来源，按生效月份升序保存，
21		// 首条为开通当月适用的开通快照，之后每条对应一次已生效的换套餐。
22		// 当前套餐标识、当前完整条件与任意历史账期的条件都统一由
23		// termsForPeriod 从中取出，开通与换套餐生效时只需在这里追加一份快照。
24		terms []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
132	// 已开通订阅继续使用开通时保存的快照。
133	func (s *Service) UpdatePlan(p Plan) error {
134		if err := validatePlan(p); err != nil {
135			return err
136		}
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if _, ok := s.plans[p.ID]; !ok {
140			return ErrPlanNotFound
141		}
142		s.plans[p.ID] = p
143		return nil
144	}
145	
146	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
147	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
148	// 首月仍收完整月费并提供完整额度。
149	//
150	// activatedAt 可以晚于当前时刻，即提前登记一份尚未生效的订阅：登记会被保留，
151	// 但在实际开通时刻到达前 Status 的 Subscribed 为 false、CurrentTerms 为零值，
152	// 也没有待换套餐安排与待取消终止时刻；此期间再次开通仍返回
153	// ErrSubscriptionExists，安排换套餐、登记取消返回 ErrSubscriptionNotActivated。
154	// 判断以实际开通时刻为界（按同一瞬间比较，带时区的开通时间结果一致），不按
155	// 开通月份提前生效；到达开通时刻后查询即显示有效订阅与登记时保存的完整套餐
156	// 条件快照，等待期间修改套餐定义不改变该快照。
157	//
158	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
159	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
160	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。同样允许登记未来
161	// 的重新开通时刻：旧订阅已结束、新订阅尚未开始的间隔中查询不显示任何生效套餐，
162	// 历史用量与账单继续可查。
163	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
164		if accountID == "" {
165			return invalidf("account id is empty")
166		}
167		if planID == "" {
168			return invalidf("plan id is empty")
169		}
170		if activatedAt.IsZero() {
171			return invalidf("activated at is zero")
172		}
173		s.mu.Lock()
174		defer s.mu.Unlock()
175		acc, ok := s.accounts[accountID]
176		if !ok {
177			return ErrAccountNotFound
178		}
179		now := s.nowUTC()
180		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
181		s.settleLocked(acc, now)
182		plan, ok := s.plans[planID]
183		if !ok {
184			return ErrPlanNotFound
185		}
186		if acc.sub != nil {
187			return ErrSubscriptionExists
188		}
189		activated := activatedAt.UTC()
190		// 重新开通时刻不得早于上一段订阅的终止时刻。
191		if n := len(acc.history); n > 0 {
192			if activated.Before(*acc.history[n-1].endedAt) {
193				return ErrResubscribeBeforeEnd
194			}
195		}
196		acc.sub = &subRecord{
197			activatedAt: activated,
198			// 开通快照即条件时间线首条：当前条件与历史出账都从这里取。
199			terms: []termsEntry{{
200				effective: MonthOf(activated),
201				terms:     termsOf(plan),
202			}},
203		}
204		return nil
205	}
206	
207	// nextMonth 返回 period 的下一个 UTC 自然月。
208	func nextMonth(period Month) Month {
209		return MonthOf(period.End())
210	}
211	
212	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
213	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
214	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
215	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
216	//
217	// 开通时刻尚未到达的订阅段只是提前登记：它尚未生效，既没有已生效的套餐条件，
218	// 也不可能有待换套餐安排或待取消终止时刻，因此在到达开通时刻前不做任何处理，
219	// 尤其不能按开通月份让条件“提前生效”。
220	func (s *Service) settleLocked(acc *account, now time.Time) {
221		sub := acc.sub
222		if sub == nil || now.Before(sub.activatedAt) {
223			return
224		}
225		current := MonthOf(now)
226		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
227			// 换套餐生效只需向条件时间线追加一份锁定快照；
228			// 当前套餐标识与当前条件都由该时间线统一导出，无需另行更新。
229			sub.terms = append(sub.terms, termsEntry{
230				effective: sub.pending.EffectivePeriod,
231				terms:     sub.pending.Terms,
232			})
233			sub.pending = nil
234		}
235		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
236			end := *sub.cancelEnd
237			sub.cancelEnd = nil
238			sub.pending = nil
239			sub.endedAt = &end
240			acc.history = append(acc.history, sub)
241			acc.sub = nil
242		}
243	}
244	
245	// coversInstant 报告订阅段是否覆盖时刻 at：半开区间 [activatedAt, end)，
246	// 开通时刻计入、终止时刻不计入。尚未生效的当前段（提前登记、开通时刻未到）
247	// 不覆盖任何时刻。订阅段的有效上界统一由 segmentEnd 给出：当前段已安排取消
248	// 时为登记的终止时刻（未到也一样，等待取消期间的事件必须落在终止之前），
249	// 已终止段为实际终止时刻，其余为无限远。所有时刻按同一瞬间比较，时区表达
250	// 不影响结果。
251	func coversInstant(sub *subRecord, at time.Time) bool {
252		if at.Before(sub.activatedAt) {
253			return false
254		}
255		if end, ended := segmentEnd(sub); ended && !at.Before(end) {
256			return false
257		}
258		return true
259	}
260	
261	// segmentEnd 返回订阅段的终止时刻（不含）：当前段已登记取消时是等待中的
262	// 终止时刻，已终止段是实际终止时刻；没有上界时 ended 为 false。
263	func segmentEnd(sub *subRecord) (time.Time, bool) {
264		if sub.endedAt != nil {
265			return *sub.endedAt, true
266		}
267		if sub.cancelEnd != nil {
268			return *sub.cancelEnd, true
269		}
270		return time.Time{}, false
271	}
272	
273	// coversMonth 报告订阅段是否让整个账期 period 成为可出账月份：
274	// 开通所在月计入（月中开通也按完整月出账），终止所在月不计入该段。
275	// 它是整月覆盖判断，不能由“月初那一刻是否被覆盖”代替——月中开通的月份
276	// 月初并不在订阅期间内，但整月仍归该订阅段出账。
277	func coversMonth(sub *subRecord, period Month) bool {
278		if period.Before(MonthOf(sub.activatedAt)) {
279			return false
280		}
281		if end, ended := segmentEnd(sub); ended && !period.Before(MonthOf(end)) {
282			return false
283		}
284		return true
285	}
286	
287	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
288	// 条件时间线按生效月份升序，取不晚于 period 的最后一条；当前条件、
289	// 是否与当前套餐相同、历史账单出账全部经过这里，因此同一账期永远得到
290	// 同一份完整条件（月费、额度、超额单价、税率同源），不受之后的换套餐
291	// 或套餐定义修改影响。调用方须保证 sub.terms 非空（订阅段创建时即有首条）。
292	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
293		t := sub.terms[0].terms
294		for _, e := range sub.terms {
295			if period.Before(e.effective) {
296				break
297			}
298			t = e.terms
299		}
300		return t
301	}
302	
303	// segmentsLocked 按订阅发生的先后返回账户的全部订阅段（已终止的历史段，
304	// 以及当前段）。订阅归属的唯一事实来源就是这些订阅段：每段的开通时刻与
305	// 终止时刻由 settleLocked 维护，时刻与整月两种覆盖判断都只经 coversInstant
306	// 与 coversMonth 访问它们，用量接收与账单出账因此对同一账户的订阅期间和
307	// 空档保持一致的依据。调用时持有 s.mu。
308	func segmentsLocked(acc *account) []*subRecord {
309		segs := make([]*subRecord, 0, len(acc.history)+1)
310		segs = append(segs, acc.history...)
311		if acc.sub != nil {
312			segs = append(segs, acc.sub)
313		}
314		return segs
315	}
316	
317	// segmentCoveringInstantLocked 返回覆盖时刻 at 的订阅段（coversInstant，
318	// 开通计入、终止不计入），没有任何段覆盖（空档、开通前、未来登记生效前）
319	// 时返回 nil。倒序检查使仍在延续的当前段优先命中。调用时持有 s.mu。
320	func segmentCoveringInstantLocked(acc *account, at time.Time) *subRecord {
321		segs := segmentsLocked(acc)
322		for i := len(segs) - 1; i >= 0; i-- {
323			if coversInstant(segs[i], at) {
324				return segs[i]
325			}
326		}
327		return nil
328	}
329	
330	// segmentCoveringMonthLocked 返回整月账期 period 出账应使用的订阅段
331	// （coversMonth：开通当月计入、终止当月不计入）。整月无任何段覆盖（早于
332	// 首段开通月，或处于两段之间的空档月）时返回 nil；月中重新开通的月份由
333	// 新订阅段覆盖，不沿用旧段条件。倒序检查使后来的段优先。调用时持有 s.mu。
334	func segmentCoveringMonthLocked(acc *account, period Month) *subRecord {
335		segs := segmentsLocked(acc)
336		for i := len(segs) - 1; i >= 0; i-- {
337			if coversMonth(segs[i], period) {
338				return segs[i]
339			}
340		}
341		return nil
342	}
343	
344	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
345	//
346	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
347	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
348	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
349	//
350	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
351	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
352	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
353	//
354	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
355	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
356	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
357	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
358		if accountID == "" {
359			return PlanChangeResult{}, invalidf("account id is empty")
360		}
361		if targetPlanID == "" {
362			return PlanChangeResult{}, invalidf("target plan id is empty")
363		}
364		s.mu.Lock()
365		defer s.mu.Unlock()
366	
367		acc, ok := s.accounts[accountID]
368		if !ok {
369			return PlanChangeResult{}, ErrAccountNotFound
370		}
371		now := s.nowUTC()
372		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
373		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
374		s.settleLocked(acc, now)
375		if acc.sub == nil {
376			return PlanChangeResult{}, ErrSubscriptionNotFound
377		}
378		if now.Before(acc.sub.activatedAt) {
379			return PlanChangeResult{}, ErrSubscriptionNotActivated
380		}
381		if acc.sub.cancelEnd != nil {
382			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
383		}
384	
385		plan, ok := s.plans[targetPlanID]
386		if !ok {
387			return PlanChangeResult{}, ErrPlanNotFound
388		}
389		// 与当前生效套餐的比较同样取当前账期适用的完整条件，
390		// 保证“当前套餐”的判断与状态查询、出账同源。
391		if targetPlanID == termsForPeriod(acc.sub, MonthOf(now)).PlanID {
392			return PlanChangeResult{}, ErrPlanChangeSamePlan
393		}
394	
395		// 已有安排且目标相同：原样返回，不重新取价。
396		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
397			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
398		}
399	
400		change := PlanChange{
401			TargetPlanID:    targetPlanID,
402			Terms:           termsOf(plan),
403			EffectivePeriod: nextMonth(MonthOf(now)),
404		}
405		acc.sub.pending = &change
406		return PlanChangeResult{Created: true, Change: change}, nil
407	}
408	
409	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
410	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
411	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
412	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
413	func (s *Service) CancelPlanChange(accountID string) error {
414		if accountID == "" {
415			return invalidf("account id is empty")
416		}
417		s.mu.Lock()
418		defer s.mu.Unlock()
419		acc, ok := s.accounts[accountID]
420		if !ok {
421			return ErrAccountNotFound
422		}
423		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
424		s.settleLocked(acc, s.nowUTC())
425		if acc.sub == nil {
426			return ErrSubscriptionNotFound
427		}
428		acc.sub.pending = nil
429		return nil
430	}
431	
432	// CancelSubscription 为当前有效订阅登记按月取消。
433	//
434	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
435	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
436	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
437	// 不把期限后移（Cancelled 为 false）。
438	//
439	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
440	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
441	//
442	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
443	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
444		if accountID == "" {
445			return CancelSubscriptionResult{}, invalidf("account id is empty")
446		}
447		s.mu.Lock()
448		defer s.mu.Unlock()
449	
450		acc, ok := s.accounts[accountID]
451		if !ok {
452			return CancelSubscriptionResult{}, ErrAccountNotFound
453		}
454		now := s.nowUTC()
455		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
456		s.settleLocked(acc, now)
457		if acc.sub == nil {
458			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
459		}
460		if now.Before(acc.sub.activatedAt) {
461			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
462		}
463	
464		// 重复取消：原样返回原终止时刻，不后移期限。
465		if acc.sub.cancelEnd != nil {
466			return CancelSubscriptionResult{
467				Cancelled:    false,
468				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
469			}, nil
470		}
471	
472		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
473		acc.sub.pending = nil
474		end := nextMonth(MonthOf(now)).Start()
475		acc.sub.cancelEnd = &end
476		return CancelSubscriptionResult{
477			Cancelled:    true,
478			Cancellation: SubscriptionCancellation{EndAt: end},
479		}, nil
480	}
481	
482	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
483	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
484	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
485	// 账户不存在或从未开通时同样失败。
486	func (s *Service) UndoCancelSubscription(accountID string) error {
487		if accountID == "" {
488			return invalidf("account id is empty")
489		}
490		s.mu.Lock()
491		defer s.mu.Unlock()
492		acc, ok := s.accounts[accountID]
493		if !ok {
494			return ErrAccountNotFound
495		}
496		// 到达终止时刻后订阅已终止：撤回失败。
497		s.settleLocked(acc, s.nowUTC())
498		if acc.sub == nil {
499			return ErrSubscriptionNotFound
500		}
501		acc.sub.cancelEnd = nil
502		return nil
503	}
504	
505	// RecordEvent 上报一条用量事件。
506	//
507	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
508	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
509	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
510	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
511	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
512	// ErrEventConflict。
513	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
514	// 但此前已接收事件的完全相同重报始终成功。
515	func (s *Service) RecordEvent(e Event) (EventResult, error) {
516		if e.AccountID == "" {
517			return EventResult{}, invalidf("account id is empty")
518		}
519		if e.EventID == "" {
520			return EventResult{}, invalidf("event id is empty")
521		}
522		if e.Quantity < 0 {
523			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
524		}
525		if e.At.IsZero() {
526			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
527		}
528		at := e.At.UTC()
529	
530		s.mu.Lock()
531		defer s.mu.Unlock()
532	
533		acc, ok := s.accounts[e.AccountID]
534		if !ok {
535			return EventResult{}, ErrAccountNotFound
536		}
537	
538		now := s.nowUTC()
539		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
540		s.settleLocked(acc, now)
541	
542		// 从未开通订阅的账户没有任何订阅段。
543		if acc.sub == nil && len(acc.history) == 0 {
544			return EventResult{}, ErrSubscriptionNotFound
545		}
546	
547		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
548		// 之后也返回成功。
549		if prev, ok := acc.events[e.EventID]; ok {
550			if !prev.at.Equal(at) || prev.qty != e.Quantity {
551				return EventResult{}, ErrEventConflict
552			}
553			return EventResult{Accepted: false, Period: prev.period}, nil
554		}
555	
556		if at.After(now) {
557			return EventResult{}, ErrEventInFuture
558		}
559		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
560		// 与出账同源于 coversInstant/coversMonth，但这里按实际瞬间判定：
561		// 月中重新开通当月虽可整月出账，开通前的事件仍被拒绝。
562		if segmentCoveringInstantLocked(acc, at) == nil {
563			return EventResult{}, ErrEventBeforeSubscription
564		}
565	
566		period := MonthOf(at)
567		if _, billed := acc.bills[period]; billed {
568			return EventResult{}, ErrMonthBilled
569		}
570		if s.isSuspendedLocked(acc, now) {
571			return EventResult{}, ErrSuspended
572		}
573	
574		total, ok := addNonNeg(acc.usage[period], e.Quantity)
575		if !ok {
576			return EventResult{}, ErrOverflow
577		}
578		// 所有校验通过后才落库：失败不消耗事件标识。
579		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
580		acc.usage[period] = total
581		return EventResult{Accepted: true, Period: period}, nil
582	}
583	
584	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
585	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
586	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
587	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
588	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
589	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
590		if accountID == "" {
591			return Bill{}, invalidf("account id is empty")
592		}
593		if period.Month < time.January || period.Month > time.December {
594			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
595		}
596		s.mu.Lock()
597		defer s.mu.Unlock()
598	
599		acc, ok := s.accounts[accountID]
600		if !ok {
601			return Bill{}, ErrAccountNotFound
602		}
603		if existing, ok := acc.bills[period]; ok {
604			return existing.bill, nil
605		}
606	
607		now := s.nowUTC()
608		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
609		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
610		// 也不会被后来的订阅覆盖。
611		s.settleLocked(acc, now)
612	
613		if acc.sub == nil && len(acc.history) == 0 {
614			return Bill{}, ErrSubscriptionNotFound
615		}
616		if period.End().After(now) {
617			return Bill{}, ErrBillMonthNotEnded
618		}
619	
620		sub := segmentCoveringMonthLocked(acc, period)
621		if sub == nil {
622			// 早于首段开通，或处于两段订阅之间的空档。
623			return Bill{}, ErrBillBeforeSubscription
624		}
625	
626		terms := termsForPeriod(sub, period)
627		bill, err := buildBill(accountID, period, terms, acc.usage[period])
628		if err != nil {
629			return Bill{}, err
630		}
631		acc.bills[period] = &billRecord{bill: bill}
632		return bill, nil
633	}
634	
635	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
636	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
637		if accountID == "" {
638			return Bill{}, invalidf("account id is empty")
639		}
640		s.mu.Lock()
641		defer s.mu.Unlock()
642		acc, ok := s.accounts[accountID]
643		if !ok {
644			return Bill{}, ErrAccountNotFound
645		}
646		rec, ok := acc.bills[period]
647		if !ok {
648			return Bill{}, ErrBillNotFound
649		}
650		return rec.bill, nil
651	}
652	
653	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
654	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
655	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
656	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
657	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
658	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
659	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
660	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
661	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
662		if accountID == "" {
663			return PaymentResult{}, invalidf("account id is empty")
664		}
665		if paymentID == "" {
666			return PaymentResult{}, invalidf("payment id is empty")
667		}
668		if amount <= 0 {
669			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
670		}
671		s.mu.Lock()
672		defer s.mu.Unlock()
673	
674		acc, ok := s.accounts[accountID]
675		if !ok {
676			return PaymentResult{}, ErrAccountNotFound
677		}
678		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
679		if prev, ok := acc.payments[paymentID]; ok {
680			if prev.period != period || prev.amount != amount {
681				return PaymentResult{}, ErrPaymentConflict
682			}
683			// 完全相同的重报仍成功，但不再次登记、不改变账单：
684			// 返回这笔付款首次成功登记完成时的余额与付清状态，
685			// 不受账单后续收款、当前余额或停用/恢复状态影响。
686			return PaymentResult{
687				Registered:  false,
688				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
689				BillBalance: prev.balance,
690				Settled:     prev.settled,
691			}, nil
692		}
693	
694		rec, ok := acc.bills[period]
695		if !ok {
696			return PaymentResult{}, ErrBillNotFound
697		}
698	
699		if amount > rec.bill.Balance {
700			return PaymentResult{}, ErrPaymentExceedsBalance
701		}
702	
703		paid, ok := addNonNeg(rec.bill.Paid, amount)
704		if !ok {
705			return PaymentResult{}, ErrOverflow
706		}
707		rec.bill.Paid = paid
708		rec.bill.Balance -= amount
709		if rec.bill.Balance == 0 {
710			rec.bill.Settled = true
711		}
712		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
713		acc.payments[paymentID] = paymentRecord{
714			period:  period,
715			amount:  amount,
716			balance: rec.bill.Balance,
717			settled: rec.bill.Settled,
718		}
719	
720		return PaymentResult{
721			Registered:  true,
722			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
723			BillBalance: rec.bill.Balance,
724			Settled:     rec.bill.Settled,
725		}, nil
726	}
727	
728	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
729	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
730		if accountID == "" {
731			return Usage{}, invalidf("account id is empty")
732		}
733		s.mu.Lock()
734		defer s.mu.Unlock()
735		acc, ok := s.accounts[accountID]
736		if !ok {
737			return Usage{}, ErrAccountNotFound
738		}
739		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
740		s.settleLocked(acc, s.nowUTC())
741		return Usage{Period: period, Total: acc.usage[period]}, nil
742	}
743	
744	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
745	func (s *Service) Status(accountID string) (AccountStatus, error) {
746		if accountID == "" {
747			return AccountStatus{}, invalidf("account id is empty")
748		}
749		s.mu.Lock()
750		defer s.mu.Unlock()
751		acc, ok := s.accounts[accountID]
752		if !ok {
753			return AccountStatus{}, ErrAccountNotFound
754		}
755	
756		now := s.nowUTC()
757		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
758		// 当前条件与订阅状态立即更新。
759		s.settleLocked(acc, now)
760	
761		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
762		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
763		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
764		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
765		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
766	
767		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
768		for m := range acc.usage {
769			periodSet[m] = struct{}{}
770		}
771		for m := range acc.bills {
772			periodSet[m] = struct{}{}
773		}
774		periods := make([]Month, 0, len(periodSet))
775		for m := range periodSet {
776			periods = append(periods, m)
777		}
778		sortMonths(periods)
779	
780		st := AccountStatus{
781			AccountID:    accountID,
782			Subscribed:   active,
783			Suspended:    s.isSuspendedLocked(acc, now),
784			MonthlyUsage: make([]Usage, 0, len(periods)),
785			Bills:        make([]BillSummary, 0, len(acc.bills)),
786		}
787		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
788		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
789		if active {
790			// 当前条件与历史出账取自同一份条件时间线：月初零点 settleLocked
791			// 追加新快照后，这里直接拿到安排时锁定的完整条件，无需另行同步。
792			st.CurrentTerms = termsForPeriod(acc.sub, MonthOf(now))
793			if acc.sub.pending != nil {
794				pending := *acc.sub.pending
795				st.PendingChange = &pending
796			}
797			if acc.sub.cancelEnd != nil {
798				end := *acc.sub.cancelEnd
799				st.ScheduledEnd = &end
800			}
801		}
802		for _, m := range periods {
803			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
804		}
805		for _, m := range periods {
806			if rec, ok := acc.bills[m]; ok {
807				b := rec.bill
808				st.Bills = append(st.Bills, BillSummary{
809					Period:   m,
810					TotalDue: b.TotalDue,
811					Paid:     b.Paid,
812					Balance:  b.Balance,
813					Settled:  b.Settled,
814					DueAt:    b.DueAt,
815				})
816			}
817		}
818		return st, nil
819	}
820	
821	// isSuspendedLocked 报告账户当前是否停用：
822	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
823	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
824		for _, rec := range acc.bills {
825			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
826				return true
827			}
828		}
829		return false
830	}
831	
832	func sortMonths(ms []Month) {
833		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
834	}
835	
836	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
837	func addNonNeg(a, b int64) (int64, bool) {
838		if a > maxInt64-b {
839			return 0, false
840		}
841		return a + b, true
842	}
843	
844	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
845	func mulNonNeg(a, b int64) (int64, bool) {
846		if a == 0 || b == 0 {
847			return 0, true
848		}
849		if a > maxInt64/b {
850			return 0, false
851		}
852		return a * b, true
853	}
854	
855	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
856	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
857		overageUnits := int64(0)
858		if totalUsage > t.IncludedUnits {
859			overageUnits = totalUsage - t.IncludedUnits
860		}
861		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
862		if !ok {
863			return Bill{}, ErrOverflow
864		}
865		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
866		if !ok {
867			return Bill{}, ErrOverflow
868		}
869		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
870		if !ok {
871			return Bill{}, ErrOverflow
872		}
873		totalDue, ok := addNonNeg(subtotal, tax)
874		if !ok {
875			return Bill{}, ErrOverflow
876		}
877		b := Bill{
878			AccountID:     accountID,
879			Period:        period,
880			Terms:         t,
881			TotalUsage:    totalUsage,
882			IncludedUnits: t.IncludedUnits,
883			OverageUnits:  overageUnits,
884			MonthlyFee:    t.MonthlyFee,
885			OverageFee:    overageFee,
886			Tax:           tax,
887			TotalDue:      totalDue,
888			Paid:          0,
889			Balance:       totalDue,
890			Settled:       totalDue == 0,
891			DueAt:         period.End().AddDate(0, 0, 7),
892		}
893		return b, nil
894	}
895	
896	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
897	// 拆分商和余数计算以避免乘积溢出 int64。
898	func rateAmount(amount, rate int64) (int64, bool) {
899		const den = 10000
900		q, r := amount/den, amount%den
901		qr, ok := mulNonNeg(q, rate)
902		if !ok {
903			return 0, false
904		}
905		rr, ok := mulNonNeg(r, rate)
906		if !ok {
907			return 0, false
908		}
909		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
910		add, ok := addNonNeg(qr, (rr+den/2)/den)
911		if !ok {
912			return 0, false
913		}
914		return add, true
915	}
916

