274	// 开通时刻计入、终止时刻不计入、空档拒绝；跨取消与重新开通的重报规则。
275	func TestEventMembershipAcrossSegments(t *testing.T) {
276		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
277		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
278		mustAccount(t, s, "u")
279		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
