300		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 2, 10, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
301			t.Fatalf("event in gap: %v", err)
302		}
