310		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "restart", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); err != nil {
311			t.Fatalf("event at reactivation: %v", err)
312		}
313	
314		// 已接受事件原样重报，在取消和重新开通后仍成功、不重复累计。
315		old := Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 1}
316		if r, err := s.RecordEvent(old); err != nil || r.Accepted {
317			t.Fatalf("identical replay across segments: %+v %v", r, err)
318		}
319		// 标识相同而时刻或数量不同仍报冲突。
320		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventConflict) {
321			t.Fatalf("same id new time: %v", err)
322		}
323		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 2}); !errors.Is(err, ErrEventConflict) {
324			t.Fatalf("same id new qty: %v", err)
325		}
326		// 空档事件被拒不消耗标识：同标识之后落在订阅期间仍可上报。
327		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); err != nil {
328			t.Fatalf("rejected gap id reused in segment: %v", err)
329		}
330	}
331	
332	// TestBackfillAfterEndAndSuspension 终止后补报旧期间未出账用量；
333	// 到期欠费时仍拒绝新增，但相同重报成功。
334	func TestBackfillAfterEndAndSuspension(t *testing.T) {
335		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
336		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
337		mustAccount(t, s, "u")
338		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
339		old := Event{AccountID: "u", EventID: "old", At: utc(2026, 1, 10, 0, 0), Quantity: 1}
340		if _, err := s.RecordEvent(old); err != nil {
341			t.Fatal(err)
342		}
343		mustCancel(t, s, "u") // end 2/1
344	
345		// 终止后补报旧订阅期间、尚未出账的用量。
346		clk.t = utc(2026, 2, 10, 0, 0)
347		if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "late", At: utc(2026, 1, 20, 0, 0), Quantity: 2}); err != nil || !r.Accepted || r.Period != jan(2026) {
348			t.Fatalf("backfill after end: %+v %v", r, err)
349		}
350		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 3 {
351			t.Fatalf("backfilled usage = %d, want 3", u.Total)
352		}
353	
354		// 出账后补报被拒，但已接受事件重报成功。
355		b := mustBill(t, s, "u", jan(2026))
356		if b.TotalUsage != 3 {
357			t.Fatalf("bill usage = %d, want 3", b.TotalUsage)
358		}
359		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "x", At: utc(2026, 1, 21, 0, 0), Quantity: 1}); !errors.Is(err, ErrMonthBilled) {
360			t.Fatalf("backfill billed month: %v", err)
361		}
362		if r, err := s.RecordEvent(old); err != nil || r.Accepted {
363			t.Fatalf("replay after billed+cancel: %+v %v", r, err)
364		}
365	
366		// 到期欠费时即使补报旧期间也拒绝新增。
367		mustAccount(t, s, "v")
368		mustSubscribe(t, s, "v", "a", utc(2026, 1, 1, 0, 0))
369		vOld := Event{AccountID: "v", EventID: "old", At: utc(2026, 1, 5, 0, 0), Quantity: 1}
370		if _, err := s.RecordEvent(vOld); err != nil {
371			t.Fatal(err)
372		}
373		clk.t = utc(2026, 2, 1, 0, 0)
374		mustBill(t, s, "v", jan(2026))
375		mustCancel(t, s, "v") // end 3/1，2 月仍在订阅覆盖内但尚未出账
376		clk.t = utc(2026, 2, 8, 0, 0)
377		st, _ := s.Status("v")
378		if !st.Suspended {
379			t.Fatal("v should be suspended")
380		}
381		// 覆盖内、未出账的 2 月新事件：到期欠费仍拒绝。
382		if _, err := s.RecordEvent(Event{AccountID: "v", EventID: "late", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
383			t.Fatalf("new event while suspended: %v", err)
384		}
385		if r, err := s.RecordEvent(vOld); err != nil || r.Accepted {
386			t.Fatalf("replay while suspended: %+v %v", r, err)
387		}
388	}
389	
390	// TestBillingAcrossCancellationAndResubscribe 取消不自动出账、空档月份失败、
391	// 各月按当时锁定条件出账，支持多次取消与重新开通且旧月份不被覆盖。
392	func TestBillingAcrossCancellationAndResubscribe(t *testing.T) {
393		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
394		// 月费不同便于识别条件：a=1000，c=3000，额度均为 0、单价 0、税 0。
395		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
396		mustPlan(t, s, planDef("c", 3000, 0, 0, 0))
397		mustAccount(t, s, "u")
398		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
399	
400		// 段一：1 月；1/15 取消，2/1 终止。
401		mustCancel(t, s, "u")
402		clk.t = utc(2026, 2, 1, 0, 0)
403		// 取消不自动出账。
404		if _, err := s.GetBill("u", jan(2026)); !errors.Is(err, ErrBillNotFound) {
405			t.Fatalf("auto-bill on cancel: %v", err)
406		}
407		// 旧订阅覆盖的已结束月份仍可出账，用当时锁定条件。
408		janBill := mustBill(t, s, "u", jan(2026))
409		if janBill.Terms.PlanID != "a" || janBill.MonthlyFee != 1000 {
410			t.Fatalf("jan bill: %+v", janBill)
411		}
412	
413		// 段二：3/1 重新开通（用新套餐），3/15 再取消，4/1 终止。
414		mustSubscribe(t, s, "u", "c", utc(2026, 3, 1, 0, 0))
415		clk.t = utc(2026, 3, 15, 0, 0)
416		mustCancel(t, s, "u")
417		clk.t = utc(2026, 4, 1, 0, 0)
418	
419		// 重开当月仍收完整月费；3 月账单按新段条件，1 月账单不被覆盖。
420		marBill := mustBill(t, s, "u", mar(2026))
421		if marBill.Terms.PlanID != "c" || marBill.MonthlyFee != 3000 {
422			t.Fatalf("mar bill: %+v", marBill)
423		}
424		gotJan, _ := s.GetBill("u", jan(2026))
425		if gotJan.MonthlyFee != 1000 || gotJan.Terms.PlanID != "a" {
426			t.Fatalf("jan bill overwritten: %+v", gotJan)
427		}
428		// 段间空档月份（2 月，已结束）出账失败。
429		if _, err := s.CreateBill("u", feb(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
430			t.Fatalf("bill feb gap: %v", err)
431		}
432		// 终止后的 4 月等其结束后同样出账失败。
433		clk.t = utc(2026, 5, 1, 0, 0)
434		if _, err := s.CreateBill("u", apr(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
435			t.Fatalf("bill apr gap: %v", err)
436		}
437	
438		// 后来修改套餐定义，已出账金额与税额不变。
439		if err := s.UpdatePlan(planDef("a", 9999, 0, 0, 1000)); err != nil {
440			t.Fatal(err)
441		}
442		gotJan, _ = s.GetBill("u", jan(2026))
443		if gotJan.MonthlyFee != 1000 || gotJan.TotalDue != 1000 {
444			t.Fatalf("jan bill changed after plan update: %+v", gotJan)
445		}
446	}
447	
448	// TestResubscribeRules 重新开通的时刻限制、快照、当月完整条款，
449	// 以及事件/付款标识不重置。
450	func TestResubscribeRules(t *testing.T) {
451		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
452		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
453		mustPlan(t, s, planDef("c", 3000, 30, 9, 0))
454		mustAccount(t, s, "u")
455		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
456		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "keep", At: utc(2026, 1, 10, 0, 0), Quantity: 1}); err != nil {
457			t.Fatal(err)
458		}
459		mustCancel(t, s, "u") // end 2/1
460		clk.t = utc(2026, 2, 1, 0, 0)
461	
462		// 开通时刻早于上次终止时刻：拒绝。
463		if err := s.Subscribe("u", "c", utc(2026, 1, 31, 23, 59)); !errors.Is(err, ErrResubscribeBeforeEnd) {
464			t.Fatalf("resubscribe before end: %v", err)
465		}
466		// 失败不留部分变更。
467		st, _ := s.Status("u")
468		if st.Subscribed {
469			t.Fatalf("partial subscription after failed resubscribe")
470		}
471		// 恰为上次终止时刻：允许，保存重新开通时的套餐条件。
472		mustSubscribe(t, s, "u", "c", utc(2026, 2, 1, 0, 0))
473		st, _ = s.Status("u")
474		if !st.Subscribed || st.CurrentTerms.PlanID != "c" || st.CurrentTerms.MonthlyFee != 3000 {
475			t.Fatalf("status after resubscribe: %+v", st)
476		}
477		// 有尚未终止的订阅时拒绝再次开通。
478		if err := s.Subscribe("u", "a", utc(2026, 2, 1, 0, 0)); !errors.Is(err, ErrSubscriptionExists) {
479			t.Fatalf("dup resubscribe: %v", err)
480		}
481	
482		// 事件标识不随重新开通重置：旧标识冲突规则依旧。
483		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "keep", At: utc(2026, 2, 5, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventConflict) {
484			t.Fatalf("event id reset by resubscribe: %v", err)
485		}
486	
487		// 付款标识不随重新开通重置。
488		janBill := mustBill(t, s, "u", jan(2026))
489		if _, err := s.RecordPayment("u", "pay1", jan(2026), janBill.TotalDue); err != nil {
490			t.Fatal(err)
491		}
492		clk.t = utc(2026, 3, 1, 0, 0)
493		febBill := mustBill(t, s, "u", feb(2026))
494		if febBill.MonthlyFee != 3000 {
495			t.Fatalf("feb (resubscribe month) bill = %+v", febBill)
496		}
497		if _, err := s.RecordPayment("u", "pay1", feb(2026), 1); !errors.Is(err, ErrPaymentConflict) {
498			t.Fatalf("payment id reset by resubscribe: %v", err)
499		}
500	}
501	
502	// TestResubscribeWithOldDebt 重新开通不清旧欠费；欠费停用规则照旧。
503	func TestResubscribeWithOldDebt(t *testing.T) {
504		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
505		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
506		mustAccount(t, s, "u")
507		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
508		clk.t = utc(2026, 2, 1, 0, 0)
509		mustBill(t, s, "u", jan(2026))
510		clk.t = utc(2026, 2, 8, 0, 0)
511		if st, _ := s.Status("u"); !st.Suspended {
512			t.Fatal("should be suspended")
513		}
514		mustCancel(t, s, "u") // end 3/1
515		clk.t = utc(2026, 3, 1, 0, 0)
516	
517		// 带着旧欠费重新开通：允许，但停用状态依旧，新用量仍被拒绝。
518		mustSubscribe(t, s, "u", "a", utc(2026, 3, 1, 0, 0))
519		st, _ := s.Status("u")
520		if !st.Subscribed || !st.Suspended {
521			t.Fatalf("resubscribe cleared debt: %+v", st)
522		}
523		clk.t = utc(2026, 3, 2, 0, 0)
524		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "m", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
525			t.Fatalf("new usage with old debt: %v", err)
526		}
527		// 结清旧债只解除停用，订阅保持有效（不改变其生命周期）。
528		if _, err := s.RecordPayment("u", "p", jan(2026), 1000); err != nil {
529			t.Fatal(err)
530		}
531		st, _ = s.Status("u")
532		if st.Suspended || !st.Subscribed {
533			t.Fatalf("status after settling old debt: %+v", st)
534		}
535		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "m", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); err != nil {
536			t.Fatalf("usage after debt cleared: %v", err)
537		}
538	}
539	
540	// TestConcurrentCancellation 并发重复取消只有一次生效，终止时刻一致；
541	// 取消/撤回/换套餐/用量/出账混跑后状态自洽，账单金额内部一致。
542	func TestConcurrentCancellation(t *testing.T) {
543		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
544		mustPlan(t, s, planDef("a", 1000, 5, 10, 0))
545		mustPlan(t, s, planDef("b", 2000, 5, 20, 0))
546		mustAccount(t, s, "u")
547		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
548	
549		const n = 64
550		var wg sync.WaitGroup
551		var mu sync.Mutex
552		var created int
553		ends := make([]time.Time, 0, n)
554		wg.Add(n)
555		for i := 0; i < n; i++ {
556			go func() {
557				defer wg.Done()
558				r, err := s.CancelSubscription("u")
559				if err != nil {
560					t.Errorf("concurrent cancel: %v", err)
561					return
562				}
563				mu.Lock()
564				if r.Cancelled {
565					created++
566				}
567				ends = append(ends, r.Cancellation.EndAt)
568				mu.Unlock()
569			}()
570		}
571		wg.Wait()
572		if created != 1 {
573			t.Fatalf("cancellations created = %d, want 1", created)
574		}
575		for _, e := range ends {
576			if !e.Equal(utc(2026, 2, 1, 0, 0)) {
577				t.Fatalf("end = %v, want 2026-02-01", e)
578			}
579		}
580	
581		// 撤回后再混跑取消/撤回/换套餐/撤回换套餐/用量，结果必须对应某个先后顺序。
582		if err := s.UndoCancelSubscription("u"); err != nil {
583			t.Fatal(err)
584		}
585		wg.Add(n * 4)
586		for i := 0; i < n; i++ {
587			go func() { defer wg.Done(); _, _ = s.CancelSubscription("u") }()
588			go func() { defer wg.Done(); _ = s.UndoCancelSubscription("u") }()
589			go func() { defer wg.Done(); _, _ = s.SchedulePlanChange("u", "b") }()
590			go func() { defer wg.Done(); _ = s.CancelPlanChange("u") }()
591		}
592		wg.Wait()
593		st, _ := s.Status("u")
594		if !st.Subscribed {
595			t.Fatalf("not subscribed in January: %+v", st)
596		}
597		// 不变量：取消安排与换套餐安排不能同时存在。
598		if st.ScheduledEnd != nil && st.PendingChange != nil {
599			t.Fatalf("both cancellation and plan change pending: %+v", st)
600		}
601	
602		// 1 月先补一笔用量，推进到 2 月并发出账：1 月账单永远适用 a，金额自洽。
603		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "base", At: utc(2026, 1, 12, 0, 0), Quantity: 8}); err != nil {
604			t.Fatal(err)
605		}
606		clk.t = utc(2026, 2, 1, 0, 0)
607		bills := make([]Bill, n)
608		wg.Add(n)
609		for i := 0; i < n; i++ {
610			go func(i int) {
611				defer wg.Done()
612				b, err := s.CreateBill("u", jan(2026))
613				if err != nil {
614					t.Errorf("concurrent bill: %v", err)
615					return
616				}
617				bills[i] = b
618			}(i)
619		}
620		wg.Wait()
621		var first Bill
622		for i, b := range bills {
623			if i == 0 {
624				first = b
625				continue
626			}
627			if b != first {
628				t.Fatalf("bills differ:\n%+v\n%+v", first, b)
629			}
630		}
631		if first.Terms.PlanID != "a" || first.MonthlyFee != 1000 || first.OverageUnits != 3 ||
632			first.OverageFee != 30 || first.TotalDue != 1030 {
633			t.Fatalf("jan bill inconsistent: %+v", first)
634		}
635	}
