	clk.t = plus8NowUTC
	r = mustCancel(t, s, "plus8-utc")
	if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEndJan) {
		t.Fatalf("utc-representation cancel = %+v, want created with end %v", r, wantEndJan)
	}

